// Original small-space adaptations. Source links demonstrate concepts, not a prescribed home workout.
const learningSources={receive:'https://www.fifatrainingcentre.com/en/practice/talent-coach-programme/build-and-progress/passing-activation-playing-and-receiving-in-between-opponents.php',wide:'https://www.fifatrainingcentre.com/en/practice/elite-sessions/in-possession/gygax-attacking-in-wide-areas.php',press:'https://www.fifatrainingcentre.com/en/practice/talent-coach-programme/press-and-regain/8v7-team-game-compact-defending.php',transition:'https://www.fifatrainingcentre.com/en/practice/elite-sessions/transition-to-defending/preparing-and-executing-counter-pressing.php',principles:'https://www.fifatrainingcentre.com/en/game/game-analysis/landing-page-core-principles.php'};
for(const [id,url]of Object.entries(learningSources))demoCatalog['study_'+id]={title:'FIFA coaching example: '+({receive:'receiving between opponents',wide:'wide combinations',press:'compact defending',transition:'reaction after losing possession',principles:'principles of play'}[id]),url,by:'FIFA Training Centre',cue:'Watch the decision and positioning. The full team drill needs a coach and more players.'};
const newConcepts=[
['bodyshape','Receive with a view','Awareness','receive','Your stance can help you see the next pass before the ball reaches you.','Scan, then open enough to see the ball and your next option.','Pressure is on your back. Should you open up into the defender?','Protect or set the ball back. An open stance helps only when the space is safe.','Pass gently off a wall. Check a side gate, then receive toward it.','Your brother points to a free gate before passing. Check, receive and play toward it.','Receiving with a fixed stance regardless of pressure.'],
['widthdepth','Make the pitch bigger','Team play','principles','Width stretches opponents sideways; depth gives a forward threat and a safe return option.','Offer a different lane from the nearest teammate.','Three teammates stand beside the ball. Where could you help?','Create a wider angle or support behind. Choose a space the passer can reach.','Lay out wide, forward and back cones. Walk each support angle and name its purpose.','Pass and move into a new lane while your brother stays on the ball.','Standing far away without a usable passing lane.'],
['thirdplayer','Use a third player','Team play','principles','A teammate can connect a pass to a runner who cannot be reached directly.','Pass, support, and look for the next runner.','Your direct pass is blocked, but a teammate can receive and see the runner. What is another route?','Use that teammate as the connection. The runner times movement to the second pass.','Use a wall as the connecting player. Pass to it, move to a new angle and collect the return.','Pass to your brother, move beyond a cone, then receive the return; imagine a third teammate making that run.','Passing to a teammate who is under too much pressure to connect.'],
['twovone','Make a 2v1 count','Attacking','wide','Two attackers can make one defender choose between the ball and a passing option.','Approach under control; pass when the defender commits.','The defender stays with the runner and leaves your lane open. Must you pass?','Carry into the open lane. Keep checking because the defender can change their choice.','Dribble toward a cone, pause, and name the carry and pass options.','One carries and one supports past a cone defender. Rehearse both choices, then swap.','Passing automatically before asking the defender a question.'],
['blindside','Move outside their view','Attacking','receive','A defender watching the ball may lose sight of a runner on the other shoulder.','Check the defender and passer before changing position.','You are hidden from the defender but the passer cannot see you either. Is that useful?','Adjust to remain reachable. Surprise matters only if the teammate can find you.','Circle a cone defender, then stop where you can see an imagined passer.','Your brother serves while you move around a cone onto its far shoulder.','Hiding from both the defender and the passer.'],
['decoy','Run to make space','Attacking','wide','Your run can pull a defender away and help a teammate even when you do not receive.','Notice who gains space when you move.','Your run takes a defender wide and opens a lane for a teammate. Was it wasted?','No. Space created for someone else is a useful outcome.','Mark a central lane and a wide lane. Walk a run away and point to the gap it opens.','One dribbles while the other moves away from a cone defender; say which route opens.','Judging every run only by whether you got the ball.'],
['weakside','Arrive from the far side','Attacking','wide','The side away from the ball can offer space for a switch or a later attacking run.','Keep seeing the ball and the defender; arrive at the useful time.','The ball is wide on the opposite side. Should you immediately crowd the ball carrier?','Hold a useful far-side position or time an arrival, following your coach’s role.','Use two wide cones. Walk a far-side position while pointing toward the ball.','Your brother pauses on one side; you check the imaginary far defender before offering a switch.','Drifting so far away that you cannot support the next action.'],
['presscue','Choose the moment to press','Defending','press','A heavy touch or closed receiver can create a chance to press when teammates can support.','Check the touch and your cover before stepping.','An opponent takes a heavy touch but you are too far away and have no cover. Sprint in?','Usually hold or delay while your team gets organised; a trigger alone is not enough.','Roll a ball different distances and practise deciding whether you can reach it safely.','Your brother alternates controlled and loose touches at walking pace. Call press or hold; no lunging.','Chasing every loose-looking touch without checking distance.'],
['pressangle','Curve your approach','Defending','press','Your approach can pressure the ball while making a dangerous pass harder.','Protect the central route as you close, according to the team plan.','You run straight at the ball and leave an easy central pass. What could change?','Approach from an angle that discourages that pass without losing control of your speed.','Mark a ball and central passing gate. Walk a curved approach that keeps the gate behind you.','Your brother holds the ball; you approach slowly and point to the pass you are trying to block.','Sprinting past the ball carrier while trying to block a pass.'],
['compact','Stay connected to your line','Defending','press','Small useful gaps let teammates cover each other; chasing alone can open the middle.','Move with the ball and check your nearest teammates.','Your line moves left but you stay far right. What gap might appear?','A central lane can open. Slide with the group while checking the far-side threat.','Use three cones as teammates. Move a ball left or right, then find a connected position.','Walk side by side as one points to the ball’s new position; keep a useful covering gap.','Getting so narrow that nobody can reach the wide attacker.'],
['trackrunner','See the runner and ball','Defending','cover','An opponent moving behind you can be more dangerous than the ball in front.','Check your shoulder and communicate who follows the run.','You stare at the passer and a runner goes behind. What information did you miss?','The runner’s movement. Check early and coordinate with the teammate covering the space.','Face a ball cone, check a second cone behind, then recover toward the goal-side gate.','Your brother walks past your shoulder; scan and track at walking pace while keeping sight of the ball cone.','Following a runner blindly without communicating a handover.'],
['restdefence','Protect while we attack','Team play','transition','Some players must remain ready to stop a counterattack while teammates attack.','Check the opponents left high and the space behind the ball.','Everyone runs beyond the ball. What happens if possession is lost?','The counterattack may have a clear route. Maintain the cover assigned by your coach.','Place three attacking cones and two opponent cones; choose a covering position and explain it.','One dribbles forward while the other walks a supporting position that can also protect the middle.','Watching the attack and forgetting the opponents behind you.'],
['counterchoice','Counter or keep it?','Team play','transition','Winning the ball creates a choice: attack an opening quickly or secure possession.','Look forward first, then choose the usable option.','You win it but the forward lane is crowded. Must you attack immediately?','No. Secure the ball, support it and look again. Speed is useful when the route is real.','Receive a wall pass and call forward or keep after checking two gates.','Your brother closes one gate before returning the ball. Choose the open route or a safe return.','Forcing a forward pass just because possession changed.'],
['tempo','Choose when to speed up','Team play','principles','A change of pace can exploit an opening; controlled possession can help create one.','Speed up when a clear advantage appears.','You are rushed but no useful route is open. Does another rushed pass help?','Often a controlled support pass helps the team see the next opening.','Alternate slow control touches with a short acceleration through a clear gate, then stop under control.','Pass gently until your brother signals an open gate; then play and move faster through it.','Confusing constant speed with good decision-making.']
];
for(const [id,title,category,source,why,cue,scenario,answer,solo,duo,mistake]of newConcepts){const l={id,title,category,why,cues:[cue],scenario,answer,solo,duo,mistake,video:[source==='cover'?'cover':'study_'+source],pressure:'Once the choice is clear, add a walking defender with your coach or another player. Keep the decision more important than speed.',evidence:'Describe one moment when you used “'+title.toLowerCase()+'”, what you noticed, and what happened.',nine:'In 9v9, relate this to your nearest teammates and the shorter distances. Follow your coach’s shape.',eleven:'In 11v11, check the next line and the far-side space as well as your nearest teammates.',prereq:['scan']};lessons.push(l);lessonById[id]=l}
const iqLevels=[['See the picture','Notice pressure and keep your next action available.',['scan','touch','pass','bodyshape','shield','turn']],['Connect play','Help teammates keep and move the ball.',['support','pocket','widthdepth','reset','thirdplayer','switch']],['Win wide','Choose when to beat, combine or deliver.',['dribble','widechoice','twovone','overlap','underlap','cross']],['Create chances','Time movement to the passer and the space.',['runs','strikercheck','blindside','decoy','finish','weakside']],['Defend together','Pressure the ball while protecting each other.',['defend','cover','presscue','pressangle','compact','trackrunner']],['Manage the game','Connect transitions, tempo and team balance.',['transition','counterchoice','restdefence','tempo','gkbuild','gkposition']]];
data.concepts=data.concepts||{};let iqLevel=0,ballIndex=0,ballDeck='touch';
function conceptKey(id){return player+'|'+prefs().format+'|'+id}
function conceptRecord(id){return data.concepts[conceptKey(id)]||{}}
function conceptSecure(id){const r=conceptRecord(id);return !!(r.explained&&r.applied&&r.recalled&&r.recalled!==r.explained)}
function iqLibrary(){appShell('Learn');const level=iqLevels[iqLevel],done=level[2].filter(conceptSecure).length;hub.insertAdjacentHTML('beforeend',`<p class="quiet-label">GAME IQ · 36 CONCEPT CARDS</p><h1>${level[0]}</h1><p>${level[1]}</p><div class="level-picker">${iqLevels.map((l,i)=>`<button data-iq-level="${i}" aria-pressed="${i===iqLevel}"><small>LEVEL ${i+1}</small>${l[0]}</button>`).join('')}</div><p class="quiet-meta">${done}/6 demonstrated · ${prefs().format}v${prefs().format} <button data-iq-format="${prefs().format==='9'?'11':'9'}">Switch format</button></p><div class="concept-grid">${level[2].map((id,i)=>{const l=lessonById[id],r=conceptRecord(id);return `<button class="concept-tile" data-focus="${id}"><small>CONCEPT ${iqLevel+1}.${i+1}</small><h2>${escapeHTML(l.title)}</h2><p>${escapeHTML(l.cues[0])}</p><span>${conceptSecure(id)?'✓ Demonstrated':r.applied?'↻ Recall on another day':r.explained?'→ Try it in play':'Open card →'}</span></button>`}).join('')}</div><details><summary>How levels work</summary><p>Explain the idea without looking, describe a real attempt, then recall it on a later day. These are player-reported milestones, not a coach assessment. Every level stays open. Rest days never erase learning.</p><p>Goalkeeper concepts in the final level also help outfield players understand build-up. No goalkeeper diving practice is assigned.</p></details>`)}
const curriculumHub=showHub;
showHub=function(page='Today'){if(page==='Learn')return iqLibrary();curriculumHub(page);if(page==='Progress')hub.insertAdjacentHTML('beforeend',`<section class="path-banner"><h2>Game IQ growth</h2><p>${lessons.filter(l=>conceptSecure(l.id)).length}/36 concepts demonstrated · ${prefs().format}v${prefs().format}</p><button data-hub="Learn">Continue the learning path →</button></section>`);if(page==='Today')hub.insertAdjacentHTML('beforeend',`<section class="path-banner"><small>YOUR GAME IQ PATH</small><h2>${iqLevels.find(l=>!l[2].every(conceptSecure))?.[0]||'Keep applying your ideas'}</h2><p>36 cards · six levels · one useful idea at a time</p><button data-hub="Learn">Explore levels →</button></section>`)};
const curriculumFocus=focusStep;
focusStep=function(){curriculumFocus();const l=lessonById[prefs().focus];if(!l)return;const level=iqLevels.findIndex(x=>x[2].includes(l.id));hub.insertAdjacentHTML('afterbegin',`<div class="lesson-badge">GAME IQ · LEVEL ${level+1} · ${prefs().format}v${prefs().format}</div>`);if(step===4){const r=conceptRecord(l.id);hub.insertAdjacentHTML('beforeend',`<section class="mastery-card"><h2>Make this idea yours</h2><p>Use these only after you actually try them.</p><button data-concept-explain>${r.explained?'✓ Explained':'I explained it without looking'}</button><label>A moment I tried it<textarea id="conceptExample" maxlength="300" placeholder="What did you notice? What did you choose?">${escapeHTML(r.example||'')}</textarea></label><button data-concept-apply>Save my real example</button><button data-concept-recall ${!r.explained||r.explained===localDate()?'disabled':''}>I recalled it on a later day</button><p id="conceptStatus" role="status">${conceptSecure(l.id)?'Demonstrated: explain + apply + later recall.':'No rush. Use it at your next practice or game.'}</p></section>`)}};
const ballDecks={touch:{name:'First Touch & Passing',ids:['touch','scan','pass']},wing:{name:'Beat & Combine',ids:['dribble','widechoice','cross']},engine:{name:'Ball & Engine',ids:['dribble','turn','pass']}};
ballSession=function(){clearSessionClock();document.body.classList.add('lesson-mode');const deck=ballDecks[ballDeck],l=lessonById[deck.ids[ballIndex]];hub.innerHTML=`<button data-hub="Today">← Sessions</button><div class="row">${Object.entries(ballDecks).map(([id,d])=>`<button data-ball-deck="${id}" aria-pressed="${id===ballDeck}">${d.name}</button>`).join('')}</div><article class="athlete-card ball-card"><div class="card-ribbon"><span>BALL LAB / ${ballIndex+1} OF 3</span><b>●</b></div><div class="card-body"><h1>${escapeHTML(l.title)}</h1>${conceptGraphic(l.id)}<p class="card-cue">${escapeHTML(l.cues[0])}</p><div class="card-stats"><div><strong>${ballDeck==='engine'?'2':'3'}</strong><span>ROUNDS</span></div><div><strong>${ballDeck==='engine'?'20s':'6'}</strong><span>${ballDeck==='engine'?'CONTROLLED WORK':'TRIES / FOOT'}</span></div><div><strong>${ballDeck==='engine'?'40s':'45s'}</strong><span>REST / ROUND</span></div></div><p>${escapeHTML(brotherMode?l.duo:l.solo)}</p><div class="row"><button data-ball-mode="solo" aria-pressed="${!brotherMode}">Solo</button><button data-ball-mode="brother" aria-pressed="${brotherMode}">With brother</button></div>${demoLink(l.video[0])}<details><summary>Why & add a decision</summary><p>${escapeHTML(l.why)}</p><p>${escapeHTML(l.pressure)}</p></details><p class="quiet-meta">${ballDeck==='engine'?'Optional six-minute conditioning block: two 20-second work / 40-second walking rounds per card. Use controlled pace, not all-out. Warm up first; skip extra conditioning near games or when tired.':'Quality first. Stop a round when touch or balance breaks down; make the next round easier.'}</p><button class="card-done" data-ball-next>${ballIndex===2?'Finish & reflect':'Finished this drill →'}</button></div></article>`};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.iqLevel!==undefined){iqLevel=Number(d.iqLevel);iqLibrary()}if(d.iqFormat){prefs().format=d.iqFormat;persist();iqLibrary()}
if(d.conceptExplain!==undefined){const k=conceptKey(prefs().focus);data.concepts[k]={...conceptRecord(prefs().focus),explained:conceptRecord(prefs().focus).explained||localDate()};persist();focusStep()}
if(d.conceptApply!==undefined){const example=$('conceptExample').value.trim();if(example.length<10){$('conceptStatus').textContent='Add a short example of what you noticed and chose.';return}const k=conceptKey(prefs().focus);data.concepts[k]={...conceptRecord(prefs().focus),applied:localDate(),example};persist();focusStep()}
if(d.conceptRecall!==undefined){const r=conceptRecord(prefs().focus);if(r.explained&&r.explained!==localDate()){r.recalled=localDate();persist();focusStep()}}
if(d.ballDeck){ballDeck=d.ballDeck;ballIndex=0;ballSession()}if(d.ballMode){brotherMode=d.ballMode==='brother';ballSession()}if(d.ballNext!==undefined){if(ballIndex<2){ballIndex++;ballSession()}else{ballIndex=0;logForm('Home session')}}
});
showHub('Today');
